<?php $request = Request::create('/api/mobile/sync/full', 'GET', ['page' => 1, 'per_page' => 100]); $controller = app()->make('App\Http\Controllers\Api\SponsorshipSyncController'); $response = $controller->getFullSync($request); $data = $response->getData()->data; $nulls = 0; foreach($data as $d) { if($d->identity_number === null || $d->orphan_name === null) $nulls++; } echo 'Nulls: ' . $nulls; 
